import json,urllib.request,urllib.error,urllib.parse,concurrent.futures,re,unicodedata
BASE='https://dados.gov.pt/api/1/datasets/'
def norm(s):return ''.join(c for c in unicodedata.normalize('NFKD',str(s).casefold()) if not unicodedata.combining(c))
def search(q):
 out={'query':q,'examined':0,'total':None,'complete':False,'matches':[],'pages':0}
 seen=set();titles=set();url=BASE+'?'+urllib.parse.urlencode({'q':q,'page_size':20})
 try:
  for i in range(10):
   u=urllib.parse.urlparse(url)
   if (u.scheme,u.hostname,u.path)!=('https','dados.gov.pt','/api/1/datasets/'):raise ValueError('unexpected pagination URL')
   req=urllib.request.Request(url,headers={'User-Agent':'Telecom-PT public catalogue metadata review','Accept':'application/json'})
   with urllib.request.urlopen(req,timeout=10) as res:
    raw=res.read(4194305)
    if len(raw)>4194304:raise ValueError('page exceeds byte limit')
    j=json.loads(raw);out['http']=res.status
   out['pages']+=1
   if out['total'] is None:out['total']=j.get('total')
   for row in j['data']:
    ident=str(row.get('id',''))
    if ident in seen:continue
    seen.add(ident);title=str(row.get('title',''));titles.add(title)
    t=norm(title+' '+str(row.get('description','')))
    signals=[]
    for name,p in [('fidelity',r'\bfideliza'),('contract_end',r'fim (?:do|de) contrato|termino (?:do|de) contrato|data de termino|data de fim do contrato'),('renewal',r'renovacao de contrato'),('private_company',r'empresa[s]? privada[s]?|sociedade[s]? privada[s]?'),('contract_in_general',r'\bcontrat')]:
     if re.search(p,t):signals.append(name)
    if signals:
     out['matches'].append({'title':title[:180],'signals':signals,'license':str(row.get('license',''))[:100]})
   nxt=j.get('next_page')
   if not nxt:out['complete']=True;break
   url=urllib.parse.urljoin(BASE,nxt)
  out['examined']=len(seen);out['unique_titles']=len(titles)
  out['complete']=out['complete'] and out['total']==out['examined']
 except Exception as e:
  out['error']=type(e).__name__+': '+str(e)[:150];out['examined']=len(seen)
 return out
with concurrent.futures.ThreadPoolExecutor(max_workers=2) as ex:results=list(ex.map(search,['telecomunicacoes','telecomunicações','fidelização','contratos telecomunicações']))
print('TELECOM_CATALOG_FULL='+json.dumps({'results':results,'scope':'complete pagination where marked; public catalog titles/descriptions only; no individual records inspected','private_contracts_obtained':0,'software_changed':False},ensure_ascii=True),flush=True)
